# the rarer statuses under `default`).
_CLASS_STATE_RESPONSES: Final = tuple(
    response
    for response in MOUNTED_OPERATIONS[
        ("post", "/api/be1/v1/classes/{class_id}/assignments")
    ]["responses"]
    if response != _IDEMPOTENCY_MISMATCH_RESPONSE
)


